    q("L3-21", "Lista 3 · Q21", "Uma escada de 6 m desliza com a base a \\(0{,}6\\ \\text{m/s}\\). Qual é a velocidade do topo quando ele está a 4 m do solo?", "\\(-\\dfrac{3\\sqrt{5}}{10}\\ \\text{m/s}\\approx-0{,}67\\ \\text{m/s}\\)", ["\\(-0{,}6\\ \\text{m/s}\\)", "\\(-\\dfrac{\\sqrt{5}}{5}\\ \\text{m/s}\\)", "\\(-0{,}45\\ \\text{m/s}\\)"], { h: "\\(x^{2}+y^{2}=36\\), com \\(x\\) a base e \\(y\\) a altura." }),
    q("L3-22", "Lista 3 · Q22", "Dois carros se aproximam de um cruzamento: um a 72 km/h para o leste e outro a 54 km/h para o sul. A que taxa se aproximam quando estão a 400 m e 300 m?", "90 km/h", ["126 km/h", "\\(\\sqrt{72^{2}+54^{2}}\\approx90\\) km/h de afastamento", "45 km/h"], { h: "\\(D^{2}=x^{2}+y^{2}\\); no instante dado \\(D=500\\) m." }),
    q("L3-23", "Lista 3 · Q23", "Tanque cônico invertido com 4 m de altura e 2 m de raio da base recebe \\(0{,}001\\ \\text{m}^{3}/\\text{min}\\). Qual é a taxa de subida do nível quando a profundidade é 1 m?", "\\(\\dfrac{4}{1000\\pi}\\ \\text{m/min}\\)", ["\\(\\dfrac{1}{1000\\pi}\\ \\text{m/min}\\)", "\\(\\dfrac{4}{100\\pi}\\ \\text{m/min}\\)", "\\(\\dfrac{1}{4000\\pi}\\ \\text{m/min}\\)"], { h: "\\(V=\\frac{\\pi}{12}h^{3}\\) porque \\(r=h/2\\)." }),
    q("L3-24", "Lista 3 · Q24", "Chapa circular cujo diâmetro varia \\(0{,}01\\ \\text{cm/min}\\). Qual é a taxa de variação da área quando o diâmetro é 30 cm?", "\\(0{,}15\\pi\\ \\text{cm}^{2}/\\text{min}\\)", ["\\(0{,}30\\pi\\ \\text{cm}^{2}/\\text{min}\\)", "\\(0{,}05\\pi\\ \\text{cm}^{2}/\\text{min}\\)", "\\(15\\pi\\ \\text{cm}^{2}/\\text{min}\\)"], { h: "\\(A=\\frac{\\pi D^{2}}{4}\\)." }),
    q("L3-25", "Lista 3 · Q25", "Incêndio circular com raio crescendo \\(1\\ \\text{m/min}\\). Taxa de aumento da área quando \\(r=20\\) m?", "\\(40\\pi\\ \\text{m}^{2}/\\text{min}\\)", ["\\(20\\pi\\ \\text{m}^{2}/\\text{min}\\)", "\\(400\\pi\\ \\text{m}^{2}/\\text{min}\\)", "\\(10\\pi\\ \\text{m}^{2}/\\text{min}\\)"], { d: "easy", h: "\\(A=\\pi r^{2}\\)." }),
    q("L3-26", "Lista 3 · Q26", "Poste de 5 m, menino de \\(1{,}6\\) m que se afasta a \\(1{,}2\\ \\text{m/s}\\). Quando ele está a 6 m do poste, a que taxa cresce a sombra e a que taxa se move a ponta da sombra?", "Sombra: \\(0{,}564\\ \\text{m/s}\\); ponta: \\(1{,}764\\ \\text{m/s}\\)", ["Sombra: \\(0{,}6\\ \\text{m/s}\\); ponta: \\(1{,}8\\ \\text{m/s}\\)", "Sombra: \\(1{,}764\\ \\text{m/s}\\); ponta: \\(0{,}564\\ \\text{m/s}\\)", "Sombra: \\(0{,}42\\ \\text{m/s}\\); ponta: \\(1{,}62\\ \\text{m/s}\\)"], { h: "Semelhança: \\(\\frac{1{,}6}{s}=\\frac{5}{s+x}\\)." }),
    q("L3-27", "Lista 3 · Q27", "Pilha cônica de areia com altura igual ao raio, crescendo \\(15\\ \\text{cm/min}\\). Vazão quando \\(h=25\\) cm?", "\\(9375\\pi\\ \\text{cm}^{3}/\\text{min}\\)", ["\\(3125\\pi\\ \\text{cm}^{3}/\\text{min}\\)", "\\(625\\pi\\ \\text{cm}^{3}/\\text{min}\\)", "\\(15625\\pi\\ \\text{cm}^{3}/\\text{min}\\)"], { h: "\\(V=\\frac{\\pi}{3}h^{3}\\)." }),
    q("L3-28", "Lista 3 · Q28", "Bola de neve esférica com volume crescendo \\(8\\ \\text{dm}^{3}/\\text{min}\\). Taxa de aumento do raio quando o diâmetro é 4 dm?", "\\(\\dfrac{1}{2\\pi}\\ \\text{dm/min}\\)", ["\\(\\dfrac{1}{\\pi}\\ \\text{dm/min}\\)", "\\(\\dfrac{2}{\\pi}\\ \\text{dm/min}\\)", "\\(\\dfrac{1}{4\\pi}\\ \\text{dm/min}\\)"], { h: "\\(V=\\frac{4}{3}\\pi r^{3}\\) e \\(r=2\\)." }),
    q("L3-29", "Lista 3 · Q29", "Às 8h o navio A está 25 km ao sul de B. A navega para oeste a 16 km/h e B para o sul a 20 km/h. Qual é a taxa de variação da distância às 8h30?", "\\(-\\dfrac{172}{17}\\ \\text{km/h}\\approx-10{,}1\\ \\text{km/h}\\)", ["\\(-17\\ \\text{km/h}\\)", "\\(-\\dfrac{172}{7}\\ \\text{km/h}\\)", "\\(+\\dfrac{172}{17}\\ \\text{km/h}\\)"], { h: "Em \\(t=0{,}5\\) h, \\(D=17\\) km; derive \\(D^{2}\\)." }),
    q("L3-30", "Lista 3 · Q30", "Farol gira uma volta a cada 15 s, a 60 m da praia retilínea. Qual é a taxa do feixe ao longo da praia no ponto a 150 m do ponto mais próximo?", "\\(3480\\pi\\ \\text{m/min}\\)", ["\\(1800\\pi\\ \\text{m/min}\\)", "\\(720\\pi\\ \\text{m/min}\\)", "\\(150\\pi\\ \\text{m/min}\\)"], { h: "\\(x=60\\operatorname{tg}\\theta\\) e \\(\\frac{d\\theta}{dt}=\\frac{2\\pi}{15}\\) rad/s." }),
    q("L3-31", "Lista 3 · Q31", "Bola de neve derretendo com raio de 30 cm a 20 cm em 45 min. Qual é a variação do volume quando \\(r=25\\) cm?", "\\(-\\dfrac{5000\\pi}{9}\\ \\text{cm}^{3}/\\text{min}\\)", ["\\(-\\dfrac{500\\pi}{9}\\ \\text{cm}^{3}/\\text{min}\\)", "\\(-\\dfrac{5000\\pi}{3}\\ \\text{cm}^{3}/\\text{min}\\)", "\\(-500\\pi\\ \\text{cm}^{3}/\\text{min}\\)"], { h: "\\(dr/dt=-10/45\\) cm/min." }),
    q("L3-32", "Lista 3 · Q32", "Pipa a 33,5 m de altura, corda a 1,5 m do solo, liberada a \\(0{,}6\\ \\text{m/s}\\). Taxa horizontal quando 38 m de corda foram liberados?", "\\(\\approx1{,}112\\ \\text{m/s}\\)", ["\\(\\approx0{,}9\\ \\text{m/s}\\)", "\\(\\approx1{,}5\\ \\text{m/s}\\)", "\\(\\approx0{,}56\\ \\text{m/s}\\)"], { h: "A altura relativa é 32 m; \\(L^{2}=x^{2}+32^{2}\\)." }),
    q("L3-33", "Lista 3 · Q33", "Balão sobe com corda liberada a \\(1\\ \\text{m/min}\\) por um carretel a \\(6{,}5\\) m da plataforma. Taxa de subida quando 150 m de corda foram liberados?", "\\(\\dfrac{150}{\\sqrt{22457{,}75}}\\ \\text{m/min}\\approx1{,}0\\ \\text{m/min}\\)", ["\\(1\\ \\text{m/min}\\)", "\\(\\dfrac{150}{6{,}5}\\ \\text{m/min}\\)", "\\(0{,}5\\ \\text{m/min}\\)"], { h: "\\(L^{2}=h^{2}+6{,}5^{2}\\)." })
