  // Fases curtas por tema e nível: cada fase reúne as questões de um bloco
  // temático (questões originais da lista) ordenadas Fácil → Intermediária
  // → Avançada, com a ordem original preservada dentro de cada nível.
  // Nenhuma fase passa de 25 questões; a cobertura é completa e sem repetição.
  const ORDEM_NIVEL = { easy: 0, medium: 1, hard: 2 };
  function porQuestoes(bank, numeros) {
    const alvos = new Set(numeros.map(String));
    return bank
      .map((item, indice) => ({ item, indice }))
      .filter(({ item }) => {
        const m = item.ref.match(/Q(\d+)/);
        return m && alvos.has(m[1]);
      })
      .sort((a, b) => (ORDEM_NIVEL[a.item.difficulty] - ORDEM_NIVEL[b.item.difficulty]) || (a.indice - b.indice))
      .map(({ item }) => item);
  }
  function intervalo(inicio, fim) {
    const qs = [];
    for (let n = inicio; n <= fim; n += 1) qs.push(n);
    return qs;
  }
  function fase(id, lista, numeroDaLista, totalDaLista, parte, totalDePartes, tema, qs, explanation, objective) {
    const bank = porQuestoes(lista, qs);
    return {
      id,
      moduleId: "m6",
      title: `Lista ${numeroDaLista} · ${parte}/${totalDePartes} — ${tema}`,
      duration: Math.max(6, Math.ceil(bank.length / 2)),
      explanation,
      objective,
      list: { number: numeroDaLista, total: totalDaLista, phase: parte, phases: totalDePartes, theme: tema, questions: qs.slice() },
      bank
    };
  }

